"""Loss-minimizing local section extraction; never executes document directives."""
import re
from html.parser import HTMLParser

SKIP_TAGS={'script','style','nav','head','noscript','template','svg','button'}
# Site chrome generated by Sphinx, MkDocs, Docusaurus and similar tools; never documentation content.
SKIP_CLASSES={'headerlink','sphinxsidebar','related','footer','md-sidebar','md-header','md-footer','theme-doc-toc-desktop',
              'pagination-nav','breadcrumbs','navbar','skip-link','copybutton','hash-link'}
SKIP_ROLES={'navigation','search','banner','contentinfo'}
VOID={'area','base','br','col','embed','hr','img','input','link','meta','source','track','wbr'}
TRAILING=re.compile(r'[\s¶🔗]+$')
RST_ADORN=r'[=\-`:\'"~^_*+#<>]'

class HTML(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.parts=[]; self.skip=None; self.heading_start=None
    def skipped(self,tag,attrs):
        a=dict(attrs)
        return tag in SKIP_TAGS or a.get('role') in SKIP_ROLES or a.get('aria-hidden')=='true' and tag in ('a','span') \
            or bool(SKIP_CLASSES.intersection((a.get('class') or '').split()))
    def handle_starttag(self,tag,attrs):
        if self.skip:
            # Count nested elements of the skipped root's tag so the matching end tag ends skipping.
            if tag==self.skip[0]: self.skip[1]+=1
            return
        if tag not in VOID and self.skipped(tag,attrs):
            self.skip=[tag,1]; return
        a=dict(attrs)
        if re.fullmatch(r'h[1-6]',tag) or (tag=='dt' and ('id' in a or 'sig' in (a.get('class') or '').split())):
            self.parts.append('\n'+('###' if tag=='dt' else '#'*int(tag[1]))+' ')
            self.heading_start=len(self.parts)
        elif tag=='pre': self.parts.append('\n```text\n')
        elif tag in ('td','th'): self.parts.append(' | ')
        elif tag in ('p','div','section','li','br','dd','dt','tr','table','blockquote'): self.parts.append('\n')
        if tag=='li': self.parts.append('- ')
    def handle_endtag(self,tag):
        if self.skip:
            if tag==self.skip[0]:
                self.skip[1]-=1
                if not self.skip[1]: self.skip=None
            return
        if (re.fullmatch(r'h[1-6]',tag) or tag=='dt') and self.heading_start is not None:
            start=self.heading_start
            self.parts[start:]=[TRAILING.sub('',re.sub(r'\s+',' ',''.join(self.parts[start:])).strip())]
            self.heading_start=None
        if tag=='pre': self.parts.append('\n```\n')
        if re.fullmatch(r'h[1-6]',tag) or tag in ('dt','p','li','dd','table'): self.parts.append('\n')
    def handle_data(self,data):
        if not self.skip: self.parts.append(data)

def markdown(text):
    """Strip YAML front matter and convert setext headings to ATX outside code fences."""
    text=re.sub(r'\A---\n.*?\n(?:---|\.\.\.)\n','',text,flags=re.S)
    lines=text.split('\n'); out=[]; fence=None
    for line in lines:
        marker=re.match(r'^\s{0,3}(`{3,}|~{3,})',line)
        if marker:
            if fence is None: fence=marker[1]
            elif marker[1][0]==fence[0] and len(marker[1])>=len(fence): fence=None
        elif fence is None and out and re.fullmatch(r' {0,3}(=+|-+)\s*',line) and out[-1].strip() \
                and not re.match(r'^\s*([-*+>|]|\d+[.)]|#)',out[-1]):
            out[-1]=('# ' if line.strip()[0]=='=' else '## ')+out[-1].strip(); continue
        out.append(line)
    return '\n'.join(out)

def rst(text):
    """Over- and underlined section titles become headings; adornment lines are dropped."""
    text=re.sub(rf'(?m)^({RST_ADORN})\1{{2,}}[ \t]*\n[ \t]*([^\n]+?)[ \t]*\n\1{{3,}}[ \t]*$',r'## \2',text)
    return re.sub(rf'(?m)^([^\s\n][^\n]*)\n({RST_ADORN})\2{{2,}}[ \t]*$',r'## \1',text)

def sections(text, suffix):
    if suffix in ('.html','.htm'):
        parser=HTML(); parser.feed(text); parser.close(); text=''.join(parser.parts)
    text=text.replace('\r\n','\n').replace('\x00','')
    if suffix in ('.md','.markdown'): text=markdown(text)
    if suffix=='.rst': text=rst(text)
    text=re.sub(r'\n{3,}','\n\n',text)
    title='Introduction'; buf=[]; fence=None
    for line in text.splitlines():
        marker=re.match(r'^\s*(`{3,}|~{3,})',line)
        if marker:
            if fence is None: fence=marker[1]
            elif marker[1][0]==fence[0] and len(marker[1])>=len(fence): fence=None
        heading=re.match(r'^#{1,6}\s+(.+)',line) if fence is None and not marker else None
        if heading:
            if ''.join(buf).strip(): yield title,'\n'.join(buf).strip()
            title=TRAILING.sub('',re.sub(r'\s#+\s*$','',heading[1])).strip()[:500] or title; buf=[line]
        else: buf.append(line.rstrip())
    if ''.join(buf).strip(): yield title,'\n'.join(buf).strip()
